+#import <Foundation/Foundation.h>
+#import <objc/message.h>
+#import <dlfcn.h>
+
+static id msg_id(id obj, SEL sel) {
+    return ((id (*)(id, SEL))objc_msgSend)(obj, sel);
+}
+
+static id msg_id1(id obj, SEL sel, id arg) {
+    return ((id (*)(id, SEL, id))objc_msgSend)(obj, sel, arg);
+}
+
+static void msg_void_id(id obj, SEL sel, id arg) {
+    ((void (*)(id, SEL, id))objc_msgSend)(obj, sel, arg);
+}
+
+int main(int argc, const char *argv[]) {
+    @autoreleasepool {
+        if (argc < 2) {
+            fprintf(stderr, "usage: realm_inspect <realm-path>\n");
+            return 1;
+        }
+
+        const char *frameworkPath = "/Users/radoniusz/Library/Developer/CoreSimulator/Devices/53CBD69C-E05C-4DAC-9A2C-2504C42CB57F/data/Containers/Bundle/Application/F357D775-32B2-4448-9387-83891861B423/Element.app/Frameworks/Realm.framework/Realm";
+        if (!dlopen(frameworkPath, RTLD_NOW)) {
+            fprintf(stderr, "dlopen failed: %s\n", dlerror());
+            return 2;
+        }
+
+        NSString *realmPath = [NSString stringWithUTF8String:argv[1]];
+        Class configClass = NSClassFromString(@"RLMRealmConfiguration");
+        Class realmClass = NSClassFromString(@"RLMRealm");
+        if (!configClass || !realmClass) {
+            fprintf(stderr, "Realm classes unavailable\n");
+            return 3;
+        }
+
+        id config = msg_id((id)configClass, sel_registerName("defaultConfiguration"));
+        if (!config) {
+            fprintf(stderr, "defaultConfiguration failed\n");
+            return 4;
+        }
+
+        msg_void_id(config, sel_registerName("setFileURL:"), [NSURL fileURLWithPath:realmPath]);
+
+        NSError *error = nil;
+        id realm = ((id (*)(id, SEL, id, NSError **))objc_msgSend)((id)realmClass, sel_registerName("realmWithConfiguration:error:"), config, &error);
+        if (!realm) {
+            fprintf(stderr, "open realm failed: %s\n", error.localizedDescription.UTF8String);
+            return 5;
+        }
+
+        id schema = [realm valueForKey:@"schema"];
+        NSArray *objectSchemas = [schema valueForKey:@"objectSchema"];
+        if (![objectSchemas isKindOfClass:[NSArray class]]) {
+            objectSchemas = [schema valueForKey:@"objectSchemas"];
+        }
+        if (![objectSchemas isKindOfClass:[NSArray class]]) {
+            fprintf(stderr, "could not read schema\n");
+            return 6;
+        }
+
+        NSString *needle = @"Team Standup";
+        for (id objectSchema in objectSchemas) {
+            NSString *className = [objectSchema valueForKey:@"className"];
+            NSArray *properties = [objectSchema valueForKey:@"properties"];
+            id results = msg_id1((id)realm, sel_registerName("objects:"), className);
+            for (id obj in results) {
+                BOOL matched = NO;
+                NSMutableDictionary *values = [NSMutableDictionary dictionary];
+                for (id prop in properties) {
+                    NSString *name = [prop valueForKey:@"name"];
+                    id value = nil;
+                    @try {
+                        value = [obj valueForKey:name];
+                    } @catch (__unused NSException *e) {
+                        continue;
+                    }
+                    if (value) {
+                        values[name] = value;
+                        if ([value isKindOfClass:[NSString class]] && [(NSString *)value rangeOfString:needle options:NSCaseInsensitiveSearch].location != NSNotFound) {
+                            matched = YES;
+                        }
+                    }
+                }
+                if (matched) {
+                    printf("CLASS %s\n", className.UTF8String);
+                    for (NSString *key in values) {
+                        id value = values[key];
+                        printf("%s: %s\n", key.UTF8String, [[value description] UTF8String]);
+                    }
+                    printf("---\n");
+                }
+            }
+        }
+    }
+    return 0;
+}
*** End Patch

